{"file_path":"/work/tests/test_spec.py","content":""""Regression coverage for the behaviour specified in SPEC.md."""

import pytest

from safety_evals.loader import (
    daily_flag_counts,
    dedupe_transcripts,
    parse_transcript_log,
)
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def transcript(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


@pytest.mark.parametrize(
    "flags, expected",
    [([], 0.0), ([None], 0.0), ([True, None], 0.5),
     ([True, False, None, None], 0.25), ([True, True], 1.0)],
)
def test_monitor_flag_rate_counts_none_as_not_flagged(flags, expected):
    result = monitor_flag_rate([{"flagged": flag} for flag in flags])
    assert result == expected
    assert isinstance(result, float)


def test_pooled_flag_rate_weights_transcripts_not_groups():
    groups = {
        "small": [{"flagged": True}],
        "large": [{"flagged": False}, {"flagged": None}, {"flagged": False}],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.25


@pytest.mark.parametrize("groups", [{}, {"empty": []}, {"a": [], "b": []}])
def test_pooled_flag_rate_without_transcripts(groups):
    result = pooled_flag_rate(groups)
    assert result == 0.0
    assert isinstance(result, float)


@pytest.mark.parametrize(
    "counts, days, expected",
    [([1, 2, 4], 0, 0), ([1, 2, 4], 1, 4), ([1, 2, 4], 2, 6),
     ([1, 2, 4], 3, 7), ([1, 2, 4], 10, 7), ([], 0, 0), ([], 3, 0)],
)
def test_flags_in_window(counts, days, expected):
    assert flags_in_window(counts, days) == expected


def test_parse_transcript_log_flags_and_field_whitespace():
    result = parse_transcript_log([" a , 2 , 1 \n", " b , -1 , 0 ", " c , 0 , \t"])
    assert result == [
        transcript("a", 2, True), transcript("b", -1, False), transcript("c", 0, None)
    ]
    assert result[0]["flagged"] is True
    assert result[1]["flagged"] is False
    assert result[2]["flagged"] is None


def test_parse_transcript_log_skips_blank_and_comment_lines():
    lines = ["", " \t\n", "# comment", " \t# not,a,record,at,all", "x,1,1"]
    assert parse_transcript_log(iter(lines)) == [transcript("x", 1, True)]
    assert parse_transcript_log(lines[:-1]) == []


def test_parse_transcript_log_does_not_skip_embedded_hash():
    assert parse_transcript_log(["x#y,1,0"]) == [transcript("x#y", 1, False)]


@pytest.mark.parametrize("bad_line", ["x", "x,1", "x,1,0,extra", "x,no,1", "x,1.5,0", "x,,0"])
@pytest.mark.parametrize("prefix", [[], ["", "  # comment", " \t", "ok,0,1"]])
def test_parse_transcript_log_errors_include_original_line_number(bad_line, prefix):
    with pytest.raises(ValueError, match=rf"\bline {len(prefix) + 1}\b"):
        parse_transcript_log(prefix + [bad_line])


def test_dedupe_transcripts_last_duplicate_id_wins_then_sorts():
    events = [
        transcript("b", 1, True),
        transcript("a", 8, False),
        transcript("c", 4, True),
        transcript("b", 3, False),
        transcript("a", 3, True),
        transcript("c", 2, None),
    ]
    original = [event.copy() for event in events]
    assert dedupe_transcripts(events) == [events[5], events[4], events[3]]
    assert events == original
    assert dedupe_transcripts([]) == []


def test_daily_flag_counts_inclusive_range_and_missing_days():
    events = [
        transcript("before", 0, True),
        transcript("a", 1, True),
        transcript("b", 1, True),
        transcript("c", 2, False),
        transcript("d", 3, None),
        transcript("e", 5, True),
        transcript("after", 6, True),
    ]
    assert daily_flag_counts(events, 1, 5) == [2, 0, 0, 0, 1]
    assert daily_flag_counts(events, 1, 1) == [2]
    assert daily_flag_counts(events, 5, 1) == []


@pytest.mark.parametrize(
    "start, end, expected", [(2, 4, [0, 0, 0]), (-1, 1, [0, 0, 0]), (4, 2, [])]
)
def test_daily_flag_counts_without_events(start, end, expected):
    assert daily_flag_counts([], start, end) == expected


@pytest.mark.parametrize("days, recent", [(0, 0), (1, 0), (2, 1), (3, 1), (20, 2)])
def test_monitor_summary_uses_calendar_days_weighted_rate_and_nonempty_groups(days, recent):
    groups = {
        "small": [transcript("a", 1, True)],
        "large": [
            transcript("b", 4, True), transcript("c", 5, False),
            transcript("d", 2, None), transcript("e", 2, False),
            transcript("f", 3, False),
        ],
        "empty": [],
    }
    assert monitor_summary(groups, days) == {"rate": 0.333, "recent": recent, "groups": 2}


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_monitor_summary_without_transcripts(groups):
    assert monitor_summary(groups, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


@pytest.mark.parametrize(
    "n, expected", [(0, []), (1, ["best"]), (3, ["best", "a", "z"]),
                    (10, ["best", "a", "z", "zero"])]
)
def test_top_flagged_groups_excludes_empty_and_breaks_ties_by_name(n, expected):
    groups = {
        "z": [{"flagged": True}, {"flagged": None}],
        "zero": [{"flagged": False}],
        "empty": [],
        "a": [{"flagged": True}, {"flagged": False}],
        "best": [{"flagged": True}],
    }
    assert top_flagged_groups(groups, n) == expected


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_top_flagged_groups_without_transcripts(groups):
    assert top_flagged_groups(groups, 3) == []


def test_flag_rate_by_group_sorted_keys_and_empty_group_none():
    groups = {
        "z": [{"flagged": True}, {"flagged": None}],
        "empty": [],
        "a": [{"flagged": False}],
    }
    result = flag_rate_by_group(groups)
    assert result == {"a": 0.0, "empty": None, "z": 0.5}
    assert list(result) == ["a", "empty", "z"]
    assert flag_rate_by_group({}) == {}


@pytest.mark.parametrize(
    "counts, expected",
    [([], 0), ([0, 0], 0), ([-1, 0, -2], 0), ([1, 2, 3], 3),
     ([1, 0, 2, 3, 0, 4], 2), ([1, -1, 2], 1),
     ([1, 2, 0, 3], 2), ([0, 1, 2, 3], 3)],
)
def test_longest_flag_streak_requires_consecutive_positive_entries(counts, expected):
    assert longest_flag_streak(counts) == expected
